package com.paicli.eval.benchmark;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.nio.file.attribute.*;
import java.io.IOException;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class SecureFilesTest {
    @TempDir Path temporary;
    @BeforeEach void privateFixtureRoot()throws IOException{SecureFiles.setPermissions(temporary,SecureFiles.PRIVATE_DIRECTORY);}
    @Test void ownerOnlyDirectoryAndFileHaveActualPermissions()throws Exception{Path directory=SecureFiles.createOwnerOnlyDirectory(temporary.resolve("private"));SecureFiles.requireOwnerOnlyDirectory(directory);Path file=SecureFiles.createTempFile(directory,"private-",".txt");Files.writeString(file,"fixture");assertEquals(SecureFiles.PRIVATE_DIRECTORY,SecureFiles.permissions(directory));assertEquals(SecureFiles.PRIVATE_FILE,SecureFiles.permissions(file));assertEquals("fixture",Files.readString(file));}
    @Test void directoryInheritanceDoesNotMakeNewRegularFilesExecutable()throws Exception{Path directory=SecureFiles.createOwnerOnlyDirectory(temporary.resolve("inherit"));Path file=SecureFiles.hasPosix(directory)?SecureFiles.createTempFile(directory,"plain-",".txt"):Files.writeString(directory.resolve("plain.txt"),"plain");Path nested=SecureFiles.hasPosix(directory)?SecureFiles.createOwnerOnlyDirectory(directory.resolve("nested")):Files.createDirectory(directory.resolve("nested"));Path nestedFile=SecureFiles.hasPosix(directory)?SecureFiles.createTempFile(nested,"nested-",".txt"):Files.writeString(nested.resolve("nested.txt"),"nested");assertEquals(SecureFiles.PRIVATE_FILE,SecureFiles.permissions(file));assertEquals(SecureFiles.PRIVATE_DIRECTORY,SecureFiles.permissions(nested));assertEquals(SecureFiles.PRIVATE_FILE,SecureFiles.permissions(nestedFile));SecureFiles.setPermissions(file,PosixFilePermissions.fromString("rwx------"));assertTrue(SecureFiles.permissions(file).contains(PosixFilePermission.OWNER_EXECUTE));}
    @Test void readOnlyDirectoryStillAllowsOwnerToTraverse()throws Exception{Path directory=SecureFiles.createOwnerOnlyDirectory(temporary.resolve("readonly"));Path child=SecureFiles.createTempFile(directory,"child-",".txt");Files.writeString(child,"retained");SecureFiles.setPermissions(directory,PosixFilePermissions.fromString("r-x------"));assertEquals(PosixFilePermissions.fromString("r-x------"),SecureFiles.permissions(directory));assertEquals("retained",Files.readString(child));SecureFiles.setPermissions(directory,SecureFiles.PRIVATE_DIRECTORY);}
    @Test void readOnlyFileDoesNotClaimOwnerWrite()throws Exception{Path file=SecureFiles.createTempFile(temporary,"readonly-",".txt");Files.writeString(file,"frozen");SecureFiles.setPermissions(file,PosixFilePermissions.fromString("r--------"));assertEquals(PosixFilePermissions.fromString("r--------"),SecureFiles.permissions(file));assertEquals("frozen",Files.readString(file));SecureFiles.setPermissions(file,SecureFiles.PRIVATE_FILE);}
    @Test void existingBroadRootIsRejectedWithoutChangingPermissions()throws Exception{Path directory=SecureFiles.createOwnerOnlyDirectory(temporary.resolve("broad"));var broad=PosixFilePermissions.fromString("rwxr-xr-x");SecureFiles.setPermissions(directory,broad);assertThrows(IOException.class,()->SecureFiles.requireOwnerOnlyDirectory(directory));assertEquals(broad,SecureFiles.permissions(directory));SecureFiles.setPermissions(directory,SecureFiles.PRIVATE_DIRECTORY);}
    @Test void trueHardLinkCountRejectsAliasEvenOutsideScannedTree()throws Exception{Path file=SecureFiles.createTempFile(temporary,"one-",".txt");Files.writeString(file,"single");assertEquals(1,SecureFiles.linkCount(file));Path alias=temporary.resolve("alias.txt");Files.createLink(alias,file);assertEquals(2,SecureFiles.linkCount(file));var attrs=Files.readAttributes(file,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);assertEquals(SecureFiles.identity(file,attrs),SecureFiles.identity(alias,Files.readAttributes(alias,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS)));assertThrows(IOException.class,()->SecureFiles.requireRegularNode(file,attrs,false,new HashSet<>()));}
    @Test void duplicateIdentityCannotBeClaimedAsAnotherNode()throws Exception{Path file=SecureFiles.createTempFile(temporary,"identity-",".txt");var attrs=Files.readAttributes(file,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);Set<Object> seen=new HashSet<>();SecureFiles.requireRegularNode(file,attrs,false,seen);assertThrows(IOException.class,()->SecureFiles.requireRegularNode(file,attrs,false,seen));}
    @Test void nonOwnerAclMetadataAuthorityCannotHideBehindReadOnlyMode()throws Exception{Path file=SecureFiles.createTempFile(temporary,"metadata-",".txt");var frozen=PosixFilePermissions.fromString("r--------");SecureFiles.setPermissions(file,frozen);if(SecureFiles.hasPosix(file)){var changed=EnumSet.copyOf(frozen);changed.add(PosixFilePermission.GROUP_WRITE);SecureFiles.setPermissions(file,changed);assertTrue(SecureFiles.permissions(file).contains(PosixFilePermission.GROUP_WRITE));}else{var view=Files.getFileAttributeView(file,AclFileAttributeView.class);var original=view.getAcl();UserPrincipal everyone=null;for(String name:List.of("Everyone","所有人","S-1-1-0"))try{everyone=file.getFileSystem().getUserPrincipalLookupService().lookupPrincipalByName(name);break;}catch(UserPrincipalNotFoundException ignored){}assertNotNull(everyone);var changed=new ArrayList<>(original);changed.add(AclEntry.newBuilder().setType(AclEntryType.ALLOW).setPrincipal(everyone).setPermissions(AclEntryPermission.WRITE_ACL).build());view.setAcl(changed);try{assertTrue(SecureFiles.permissions(file).contains(PosixFilePermission.OTHERS_WRITE));assertNotEquals(frozen,SecureFiles.permissions(file));}finally{view.setAcl(original);}}SecureFiles.setPermissions(file,SecureFiles.PRIVATE_FILE);}
    @Test void unknownCreationAttributeCannotTruncateExistingContent()throws Exception{Path file=SecureFiles.createTempFile(temporary,"kept-",".txt");Files.writeString(file,"user fixture");FileAttribute<String> unsupported=new FileAttribute<>(){public String name(){return "fake:permissions";}public String value(){return "any";}};assertThrows(IOException.class,()->SecureFiles.newByteChannel(file,Set.of(StandardOpenOption.WRITE,StandardOpenOption.TRUNCATE_EXISTING),unsupported));assertEquals("user fixture",Files.readString(file));}
    @Test void aclReadOnlyTamperDoesNotPassFrozenPermissionVerification()throws Exception{Path file=SecureFiles.createTempFile(temporary,"tamper-",".txt");Files.writeString(file,"frozen");var frozen=PosixFilePermissions.fromString("r--------");SecureFiles.setPermissions(file,frozen);assertEquals(frozen,SecureFiles.permissions(file));if(!SecureFiles.hasPosix(file))assertThrows(IOException.class,()->Files.writeString(file,"overwritten"));SecureFiles.setPermissions(file,SecureFiles.PRIVATE_FILE);assertNotEquals(frozen,SecureFiles.permissions(file));assertEquals("frozen",Files.readString(file));}
    @Test void linkParentCannotBeAcceptedAsOwnerOnlyCanonicalDirectory()throws Exception{Path outside=SecureFiles.createOwnerOnlyDirectory(temporary.resolve("outside"));Path link=temporary.resolve("link");if(SecureFiles.hasPosix(temporary))Files.createSymbolicLink(link,outside);else{Path cmd=Path.of(System.getenv("SystemRoot"),"System32","cmd.exe");String command="mklink /J \""+link+"\" \""+outside+"\"";assertFalse(command.matches(".*[&|<>%].*"));Process process=new ProcessBuilder(cmd.toString(),"/d","/c",command).redirectErrorStream(true).start();assertTrue(process.waitFor(3,java.util.concurrent.TimeUnit.SECONDS));assertEquals(0,process.exitValue());}assertThrows(IOException.class,()->SecureFiles.requireOwnerOnlyDirectory(link));assertThrows(IOException.class,()->SecureFiles.createTempFile(link,"blocked-",".txt"));try(var children=Files.list(outside)){assertEquals(0,children.count());}Files.delete(link);}
}
